import { withToolbar } from "@repo/feature-flags/lib/toolbar";
import { config, withAnalyzer } from "@repo/next-config";
import { withLogging, withSentry } from "@repo/observability/next-config";
import type { NextConfig } from "next";
import { env } from "@/env";

export default async (): Promise<NextConfig> => {
  let nextConfig: NextConfig = await withToolbar(withLogging(config));

  nextConfig.reactCompiler = true;
  nextConfig.poweredByHeader = false;

  // The landing page demos Cache Components on itself (static shell, `use
  // cache`, streamed Suspense holes) — the flag is load-bearing content.
  nextConfig.cacheComponents = true;

  // Tailwind's output for this site is small and render-blocking, and first
  // paint was waiting on a whole round trip for it. Inlining trades a bigger
  // HTML document for one less blocking request, which is the trade the docs
  // recommend for atomic CSS.
  nextConfig.experimental = { ...nextConfig.experimental, inlineCss: true };

  nextConfig.images?.remotePatterns?.push({
    hostname: "picsum.photos",
    protocol: "https",
  });

  const redirects: NextConfig["redirects"] = async () => [
    {
      destination: "/legal/privacy",
      source: "/legal",
      statusCode: 301,
    },
  ];

  nextConfig.redirects = redirects;

  if (env.VERCEL) {
    nextConfig = withSentry(nextConfig);
  }

  if (env.ANALYZE === "true") {
    nextConfig = withAnalyzer(nextConfig);
  }

  return nextConfig;
};
import { isToolbarEnabled } from "@repo/feature-flags/lib/toolbar-enabled";
import { internationalizationMiddleware } from "@repo/internationalization/middleware";
import { parseError } from "@repo/observability/error";
import { secure } from "@repo/security";
import { type NextProxy, type NextRequest, NextResponse } from "next/server";
import { env } from "@/env";
import {
  securityHeaders,
  securityOptions,
  securityOptionsWithToolbar,
  withSecurityHeaders,
} from "@/lib/security-headers";
import { TICKETS } from "@/lib/tickets";

export const config = {
  matcher: [
    // Skip Next.js internals and all static files, unless found in search params
    "/((?!_next|monitoring|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
    // Always run for API routes
    "/api/:path*",
  ],
};

// Only widen the CSP where the toolbar actually renders. Keying this on
// FLAGS_SECRET alone meant production carried vercel.live allowances for a
// toolbar it no longer loads.
const headerOptions = isToolbarEnabled()
  ? securityOptionsWithToolbar
  : securityOptions;

// Custom middleware for Arcjet security checks
const arcjetMiddleware = async (request: NextRequest) => {
  if (!env.ARCJET_KEY) {
    return;
  }

  try {
    await secure(
      [
        // See https://docs.arcjet.com/bot-protection/identifying-bots
        "CATEGORY:SEARCH_ENGINE", // Allow search engines
        "CATEGORY:PREVIEW", // Allow preview links to show OG images
        "CATEGORY:MONITOR", // Allow uptime monitoring services
      ],
      request
    );
  } catch (error) {
    // The reason goes to Sentry; the visitor gets the same line either way.
    parseError(error);
    return NextResponse.json({ error: "Access denied" }, { status: 403 });
  }
};

// Skip i18n rewriting for routes outside [locale] (i18n middleware's own
// matcher excludes these, but proxy.ts runs it for all matched routes via
// createNEMO, causing rewrites to /en/... paths that don't exist). The two
// metadata files live at the app root, where Next serves them from.
const UNLOCALIZED = new Set(["/robots.txt", "/sitemap.xml"]);

// The pages after the waitlist link and the unsubscribe button are only
// for the visitor who just came from them: without the ticket their
// redirect set, the address is a 404.
const ticketed = (request: NextRequest) => {
  const { pathname } = request.nextUrl;
  const ticket = TICKETS.find((t) => t.path === pathname);
  if (ticket && !request.cookies.has(ticket.cookie)) {
    return NextResponse.rewrite(
      new URL(`${ticket.path}/not-found`, request.url),
      { status: 404 }
    );
  }
};

const i18nWithExclusions = (request: NextRequest) => {
  const { pathname } = request.nextUrl;
  if (
    UNLOCALIZED.has(pathname) ||
    pathname.startsWith("/api") ||
    pathname.startsWith("/confirmed") ||
    pathname.startsWith("/unsubscribe") ||
    pathname.startsWith("/.well-known")
  ) {
    return;
  }
  return internationalizationMiddleware(request);
};

// The chain: Arcjet first, so a refusal ends the request before any
// rewrite; then the locale rewrite; then a plain `next()`. Whichever
// response comes back, the security headers are merged onto it rather than
// offered as a fallback that never gets used.
export const proxy: NextProxy = async (request: NextRequest) => {
  const response =
    (await arcjetMiddleware(request)) ??
    ticketed(request) ??
    (await i18nWithExclusions(request)) ??
    NextResponse.next();
  return withSecurityHeaders(response, securityHeaders(headerOptions));
};
import "./styles.css";
import { AnalyticsProvider } from "@repo/analytics/provider";
import { DesignSystemProvider } from "@repo/design-system";
import { cn } from "@repo/design-system/lib/utils";
import { Toolbar } from "@repo/feature-flags/components/toolbar";
import type { Metadata } from "next";
import type { ReactNode } from "react";
import { jetbrainsMono, switzer } from "@/app/fonts";
import { env } from "@/env";

// Resolves every page's relative /api/og image to an absolute URL in the
// rendered og:image tag — crawlers don't do relative. Pages set their own
// title and description; this is the floor under the ones that don't.
export const metadata: Metadata = {
  description: "The unofficial live playground for Next.js and Vercel.",
  metadataBase: new URL(env.NEXT_PUBLIC_WEB_URL),
  title: "hasToggle — the unofficial live playground for Next.js & Vercel",
};

interface RootLayoutProperties {
  readonly children: ReactNode;
}

const RootLayout = ({ children }: RootLayoutProperties) => (
  // Switzer and JetBrains Mono are the marketing faces, so this app declares
  // them once at the root rather than layering them over the design system's
  // Geist. Loading both pairs meant preloading ~141 KB of Geist that the
  // marketing tree overrides on the very next element and never paints.
  <html
    className={cn(
      switzer.variable,
      jetbrainsMono.variable,
      "touch-manipulation scroll-smooth font-sans antialiased"
    )}
    // The attribute must accompany scroll-smooth: the router only suppresses
    // smooth scrolling during route-transition scroll resets when it sees it
    // (it won't pay getComputedStyle to find out). Without it, every page
    // navigation animates its scroll-to-top from the old position. Hash
    // scrolls are exempt from the suppression, so anchors keep the glide.
    data-scroll-behavior="smooth"
    lang="en"
    suppressHydrationWarning
  >
    <body>
      <AnalyticsProvider>
        <DesignSystemProvider>{children}</DesignSystemProvider>
      </AnalyticsProvider>
      <Toolbar />
    </body>
  </html>
);

export default RootLayout;
import { locales } from "@repo/internationalization";
import { NuqsAdapter } from "nuqs/adapters/next/app";
import type { ReactNode } from "react";

// With Cache Components, `params.locale` counts as runtime data unless the
// build knows the possible values. Listing them keeps every locale variant
// prerenderable instead of forcing pages behind Suspense. The site is
// English only for now (one locale in @repo/internationalization); the
// proxy's locale rewrite files any other first segment under /en, where
// it is a 404 rather than an English page under a foreign path.
export const generateStaticParams = (): { locale: string }[] =>
  locales.map((locale) => ({ locale }));

interface LocaleLayoutProperties {
  readonly children: ReactNode;
}

const LocaleLayout = ({ children }: LocaleLayoutProperties) => (
  <div className="font-switzer selection:bg-ht-cyan-400/30">
    <NuqsAdapter>{children}</NuqsAdapter>
  </div>
);

export default LocaleLayout;
import { JetBrains_Mono } from "next/font/google";
import localFont from "next/font/local";

/* The marketing faces, self-hosted.
 *
 * These used to arrive as two `<link rel="stylesheet">` tags pointing at
 * api.fontshare.com and fonts.googleapis.com. Both were render-blocking and
 * cross-origin, so first paint waited on two DNS + TLS handshakes before it
 * could wait on the font files themselves — about a second of nothing, and the
 * hero footnote (the LCP element) is set in the mono face, so it paid the full
 * bill. Serving both faces from our own origin removes the handshakes, lets
 * Next.js emit preload hints, and keeps the bytes on the same connection as the
 * document.
 *
 * Switzer is vendored as woff2 under this directory; Fontshare has no npm
 * package and the ITF Free Font License permits self-hosting. JetBrains Mono
 * comes through next/font/google, which downloads and fingerprints it at build
 * time rather than at request time.
 */

export const switzer = localFont({
  display: "swap",
  fallback: ["system-ui", "sans-serif"],
  src: [
    { path: "./Switzer-Regular.woff2", style: "normal", weight: "400" },
    { path: "./Switzer-Medium.woff2", style: "normal", weight: "500" },
    { path: "./Switzer-Semibold.woff2", style: "normal", weight: "600" },
    { path: "./Switzer-Bold.woff2", style: "normal", weight: "700" },
  ],
  variable: "--font-switzer-sans",
});

export const jetbrainsMono = JetBrains_Mono({
  display: "swap",
  fallback: [
    "ui-monospace",
    "SFMono-Regular",
    "Menlo",
    "Monaco",
    "Consolas",
    "monospace",
  ],
  subsets: ["latin"],
  variable: "--font-jetbrains-mono",
  weight: ["400", "500", "600"],
});
import { initializeAnalytics } from "@repo/analytics/instrumentation-client";
import { initializeSentry } from "@repo/observability/client";
import { captureRouterTransitionStart } from "@sentry/nextjs";

initializeSentry();
initializeAnalytics();

export const onRouterTransitionStart = captureRouterTransitionStart;
